#!/bin/bash
set -e

# Fix: the full @sparticuz/chromium package (~300MB uncompressed) exceeds
# Vercel's serverless function size limit and gets silently truncated on
# deploy, which is why libnss3.so was missing at runtime. Switching to
# @sparticuz/chromium-min, which downloads the Chromium binary from a
# remote URL at cold start instead of bundling it.
# Run this from your veda-hmis repo root in Codespaces.

# Remove the old (too-large) dependency first
npm uninstall @sparticuz/chromium 2>/dev/null || true

echo "" | base64 -d > "package.json"
echo "Wrote package.json"

echo "" | base64 -d > "next.config.js"
echo "Wrote next.config.js"

mkdir -p "lib"
echo "" | base64 -d > "lib/pdf-generator.js"
echo "Wrote lib/pdf-generator.js"

npm install

git add package.json package-lock.json next.config.js lib/pdf-generator.js
git commit -m "Fix: use @sparticuz/chromium-min to stay under Vercel function size limit"
git push

echo "Done. After Vercel redeploys, retest:"
echo "https://portal.vedaeyehospital.com/api/test-invoice-pdf/bf96cb51-46bd-45ad-8562-08665adba446"
